import { test, expect } from '@playwright/test';

test.describe('Data Reviewer - Verify Table Records', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tables');
  });

  test('should verify table #table1 has correct header and rows', async ({ page }) => {
    // Verify table header exists
    const tableHeader = page.getByRole('heading', { name: /last name|first name|email|due/i });
    await expect(tableHeader).toBeVisible();

    // Verify header contains correct column headings
    const headers = page.getByRole('rowheader', { name: /last name|first name|email|due/i });
    await expect(headers).toHaveCount(4);

    const headerTexts = await page.evaluate(() => {
      const headers = Array.from(document.querySelectorAll('[data-testid="table-header"]'));
      return headers.map(header => header.textContent.trim());
    });
    expect(headerTexts).toEqual(['Last Name', 'First Name', 'Email', 'Due']);

    // Verify table body contains 4 rows
    const tableBody = page.getByRole('row', { name: /row/i });
    await expect(tableBody).toHaveCount(4);

    // Verify one row contains the email 'jsmith@gmail.com'
    const emailRow = page.getByText('jsmith@gmail.com');
    await expect(emailRow).toBeVisible();

    // Verify the same row contains the last name 'Smith'
    const lastNameCell = page.getByText('Smith');
    await expect(lastNameCell).toBeVisible();

    // Verify the row contains the correct email and last name
    const rowText = await emailRow.evaluate((el) => el.textContent.trim());
    expect(rowText).toContain('jsmith@gmail.com');
    expect(rowText).toContain('Smith');
  });

  test('should verify table #table1 has correct data in each cell', async ({ page }) => {
    // Verify table header exists
    const tableHeader = page.getByRole('heading', { name: /last name|first name|email|due/i });
    await expect(tableHeader).toBeVisible();

    // Verify table body contains 4 rows
    const tableBody = page.getByRole('row', { name: /row/i });
    await expect(tableBody).toHaveCount(4);

    // Verify each row has the correct data
    const rows = page.getByRole('row', { name: /row/i });
    for (let i = 0; i < rows.length; i++) {
      const row = rows.nth(i);
      const lastNameCell = row.getByText('Smith');
      const firstNameCell = row.getByText('John');
      const emailCell = row.getByText('jsmith@gmail.com');
      const dueCell = row.getByText('2023-12-31');

      await expect(lastNameCell).toBeVisible();
      await expect(firstNameCell).toBeVisible();
      await expect(emailCell).toBeVisible();
      await expect(dueCell).toBeVisible();
    }
  });
});
